    Bug 2043529 - Fix three uses of non-localized folder name in front-end. r=freaktechnik


    This applies to the folder location widget and two different save message
    dialogs from the composer.

    Differential Revision: https://phabricator.services.mozilla.com/D303603

diff --git a/mail/components/compose/content/MsgComposeCommands.js b/mail/components/compose/content/MsgComposeCommands.js
index 097585ab4c9..6729250a360 100644
--- a/mail/components/compose/content/MsgComposeCommands.js
+++ b/mail/components/compose/content/MsgComposeCommands.js
@@ -7995,7 +7995,7 @@ function ComposeCanClose() {
       window,
       getComposeBundle().getString("saveDlogTitle"),
       getComposeBundle().getFormattedString("saveDlogMessages3", [
-        draftsFolder.name,
+        draftsFolder.localizedName,
       ]),
       Services.prompt.BUTTON_TITLE_SAVE * Services.prompt.BUTTON_POS_0 +
         Services.prompt.BUTTON_TITLE_CANCEL * Services.prompt.BUTTON_POS_1 +
@@ -10563,7 +10563,7 @@ function DisplaySaveFolderDlg(folderURI) {
     const bundle = getComposeBundle();
     const SaveDlgTitle = bundle.getString("SaveDialogTitle");
     const dlgMsg = bundle.getFormattedString("SaveDialogMsg", [
-      msgfolder.name,
+      msgfolder.localizedName,
       msgfolder.server.prettyName,
     ]);

diff --git a/mail/components/unifiedtoolbar/content/items/folder-location-button.mjs b/mail/components/unifiedtoolbar/content/items/folder-location-button.mjs
index d27f5701051..1576949a2f2 100644
--- a/mail/components/unifiedtoolbar/content/items/folder-location-button.mjs
+++ b/mail/components/unifiedtoolbar/content/items/folder-location-button.mjs
@@ -68,7 +68,7 @@ class FolderLocationButton extends MailTabButton {
       return;
     }
     this.disabled = false;
-    this.label.textContent = gFolder.name;
+    this.label.textContent = gFolder.localizedName;
     this.#icon.style = `content: url(${lazy.FolderUtils.getFolderIcon(
       gFolder
     )});`;
